function jsonToYaml(obj, indent = 0) {
  const spacing = '  '.repeat(indent);
  let yaml = '';

  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      const type = typeof value;

      if (value !== null && type === 'object' && !Array.isArray(value)) {
        // Handle Nested Objects
        yaml += `${spacing}${key}:\n${jsonToYaml(value, indent + 1)}`;
      } else if (Array.isArray(value)) {
        // Handle Arrays
        yaml += `${spacing}${key}:\n`;
        value.forEach(item => {
          if (typeof item === 'object') {
            // Array of objects
            const entries = Object.entries(item);
            entries.forEach(([subKey, subVal], i) => {
              const prefix = i === 0 ? '- ' : '  ';
              yaml += `${spacing}  ${prefix}${subKey}: ${subVal}\n`;
            });
          } else {
            // Simple array
            yaml += `${spacing}  - ${item}\n`;
          }
        });
      } else {
        // Handle Primitive Values (string, number, boolean)
        yaml += `${spacing}${key}: ${value}\n`;
      }
    }
  }
  return yaml;
}

function yamlToJson(yamlString) {
  const lines = yamlString.split('\n');
  const result = {};
  const stack = [result];
  const indentStack = [-1];

  lines.forEach(line => {
    // Skip empty lines or comments
    if (!line.trim() || line.trim().startsWith('#')) return;

    const indent = line.search(/\S/);
    const [key, ...valParts] = line.trim().split(':');
    let value = valParts.join(':').trim();

    // Handle basic types
    if (value === 'true') value = true;
    else if (value === 'false') value = false;
    else if (!isNaN(value) && value !== '') value = Number(value);

    // Pop the stack if we are moving back out of indentation
    while (indent <= indentStack[indentStack.length - 1]) {
      stack.pop();
      indentStack.pop();
    }

    const currentObj = stack[stack.length - 1];

    if (value === '') {
      // It's a nested object
      currentObj[key] = {};
      stack.push(currentObj[key]);
      indentStack.push(indent);
    } else {
      // It's a leaf node
      currentObj[key] = value;
    }
  });

  return JSON.stringify(result, null, 2);
}


for (const item of $input.all()) {

  if(item.jsonValue?.yaml){
    item.json.jsonValue = JSON.parse(yamlToJson(item.json.yamlValue))
  } else if( item.json?.json){
    item.json.yamlValue = JSON.parse(jsonToYaml(item.json.jsonValue))
  }

}

return $input.all();

